parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "cro_score": { "type": "integer", "minimum": 0, "maximum": 100 },
    "verdict": { "type": "string" },
    "roast": { "type": "string" },
    "categories": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "name": { "type": "string", "enum": ["Headline & Value Proposition", "Call To Action", "Social Proof & Trust", "Visual Hierarchy & Design", "Copywriting & Clarity", "Mobile & Performance"] },
          "score": { "type": "integer", "minimum": 0, "maximum": 10 },
          "comment": { "type": "string" }
        },
        "required": ["name", "score", "comment"]
      }
    },
    "tips": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "priority": { "type": "string", "enum": ["High", "Medium", "Low"] },
          "title": { "type": "string" },
          "problem": { "type": "string" },
          "fix": { "type": "string" },
          "example": { "type": "string" }
        },
        "required": ["priority", "title", "problem", "fix", "example"]
      }
    }
  },
  "required": ["cro_score", "verdict", "roast", "categories", "tips"]
}

parameters.jsCode:
const item = $input.first().json;
const data = item.output ?? item;
const cfg = $('Configuration').first().json;
const url = cfg.landing_page_url || '';
const lang = cfg.output_language || 'English';
const score = Number(data.cro_score ?? 0);
const verdict = data.verdict || '';
const roast = data.roast || '';
const categories = Array.isArray(data.categories) ? data.categories : [];
const tips = Array.isArray(data.tips) ? data.tips : [];
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
const scoreColor = score >= 75 ? '#16a34a' : score >= 50 ? '#f59e0b' : '#dc2626';
const catRows = categories.map(function(c){var cs=Number(c.score||0);var bar=cs>=7?'#16a34a':cs>=4?'#f59e0b':'#dc2626';return '<div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-weight:600;"><span>'+esc(c.name)+'</span><span>'+cs+'/10</span></div><div style="background:#e5e7eb;border-radius:6px;height:8px;margin-top:4px;"><div style="width:'+(cs*10)+'%;background:'+bar+';height:8px;border-radius:6px;"></div></div><div style="color:#4b5563;font-size:14px;margin-top:4px;">'+esc(c.comment)+'</div></div>';}).join('');
const prio = {High:'#dc2626',Medium:'#f59e0b',Low:'#16a34a'};
const tipCards = tips.map(function(t,i){var pc=prio[t.priority]||'#6b7280';return '<div style="border:1px solid #e5e7eb;border-left:4px solid '+pc+';border-radius:10px;padding:16px;margin:12px 0;background:#fff;"><div style="display:flex;align-items:center;gap:8px;"><span style="background:'+pc+';color:#fff;font-size:12px;font-weight:700;padding:2px 8px;border-radius:999px;">'+esc(t.priority)+'</span><span style="font-weight:700;font-size:16px;">'+(i+1)+'. '+esc(t.title)+'</span></div><p style="margin:10px 0 4px;"><strong>Problem:</strong> '+esc(t.problem)+'</p><p style="margin:4px 0;"><strong>Fix:</strong> '+esc(t.fix)+'</p><p style="margin:4px 0;background:#f9fafb;padding:8px;border-radius:6px;"><strong>Example:</strong> '+esc(t.example)+'</p></div>';}).join('');
const html = '<div style="max-width:760px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111827;"><div style="text-align:center;margin-bottom:8px;"><div style="font-size:14px;color:#6b7280;">CRO audit for</div><div style="font-size:16px;font-weight:600;word-break:break-all;">'+esc(url)+'</div></div><div style="text-align:center;margin:16px 0;"><div style="display:inline-block;width:120px;height:120px;border-radius:50%;border:8px solid '+scoreColor+';line-height:104px;font-size:38px;font-weight:800;color:'+scoreColor+';">'+score+'</div><div style="font-size:13px;color:#6b7280;margin-top:4px;">CRO score / 100</div><p style="font-size:17px;font-weight:600;margin:12px auto;max-width:600px;">'+esc(verdict)+'</p></div><h2 style="font-size:18px;border-bottom:2px solid #111827;padding-bottom:6px;">The roast</h2><p style="white-space:pre-wrap;line-height:1.6;color:#374151;">'+esc(roast)+'</p><h2 style="font-size:18px;border-bottom:2px solid #111827;padding-bottom:6px;margin-top:24px;">Category scores</h2>'+catRows+'<h2 style="font-size:18px;border-bottom:2px solid #111827;padding-bottom:6px;margin-top:24px;">Optimization tips</h2>'+tipCards+'<p style="text-align:center;color:#9ca3af;font-size:12px;margin-top:24px;">Generated with n8n + OpenAI</p></div>';
const summary = tips.slice(0,3).map(function(t,i){return (i+1)+'. '+t.title;}).join(' | ');
return [{ json: { report_html: html, cro_score: score, verdict: verdict, summary: summary, url: url, language: lang, analyzed_at: new Date().toISOString() } }];
